#!/usr/bin/env python3
"""#2517 — ratified D7 conformance witness.

Owner authority:
  D7 = Sound7/Sanskrit sound-related objects
     + local śloka/sūtra ordinal numbering/provenance
  D7 != general arithmetic Number

This is a semantic-domain guard, not an occupancy table.
"""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
from typing import Any

ROOT = Path(__file__).resolve().parents[2]
TEXT7 = ROOT / "crates" / "sens" / "src" / "text7.rs"
WIRE_TEST = ROOT / "crates" / "sens" / "tests" / "text7_canonical_wire.rs"

MAX7 = 0b1111111


class DomainError(ValueError):
    pass


class RoleError(ValueError):
    pass


class WidthError(ValueError):
    pass


@dataclass(frozen=True)
class D7Object:
    bits: int
    role: str

    def __post_init__(self) -> None:
        if not 0 <= self.bits <= MAX7:
            raise WidthError(self.bits)
        if self.role not in {"sound-cell", "local-ordinal"}:
            raise RoleError(self.role)


@dataclass(frozen=True)
class ArithmeticNumber:
    value: int


@dataclass(frozen=True)
class D14ProvenanceLink:
    ordinal: D7Object
    d14_node: str

    def __post_init__(self) -> None:
        if self.ordinal.role != "local-ordinal":
            raise RoleError("only D7 local ordinals may form this provenance link")


def semantic_key(value: Any) -> tuple[Any, ...]:
    if isinstance(value, D7Object):
        return ("D7", value.role, value.bits)
    if isinstance(value, ArithmeticNumber):
        return ("ArithmeticNumber", value.value)
    if isinstance(value, D14ProvenanceLink):
        return (
            "D7->D14-provenance",
            semantic_key(value.ordinal),
            value.d14_node,
        )
    raise DomainError(type(value).__name__)


def arithmetic_add(left: Any, right: Any) -> ArithmeticNumber:
    if not isinstance(left, ArithmeticNumber) or not isinstance(right, ArithmeticNumber):
        raise DomainError("DOMAIN-MISMATCH")
    return ArithmeticNumber(left.value + right.value)


def arithmetic_mul(left: Any, right: Any) -> ArithmeticNumber:
    if not isinstance(left, ArithmeticNumber) or not isinstance(right, ArithmeticNumber):
        raise DomainError("DOMAIN-MISMATCH")
    return ArithmeticNumber(left.value * right.value)


def arithmetic_recip(value: Any) -> tuple[int, int]:
    if not isinstance(value, ArithmeticNumber):
        raise DomainError("DOMAIN-MISMATCH")
    if value.value == 0:
        raise ZeroDivisionError
    return (1, value.value)


def require_role(value: D7Object, role: str) -> D7Object:
    if value.role != role:
        raise RoleError("ROLE-MISMATCH")
    return value


def erase_role(value: D7Object) -> int:
    return value.bits


def interpret_erased_d7(bits: int) -> D7Object:
    # Width alone cannot decide whether a 7-bit D7 object is a sound cell or
    # a local ordinal. Fail closed instead of guessing.
    if not 0 <= bits <= MAX7:
        raise WidthError(bits)
    raise RoleError("AMBIGUOUS-WITHOUT-ROLE")


def source_contract_gate() -> None:
    text = TEXT7.read_text(encoding="utf-8")
    assert "pub const LOGICAL_WIDTH: u8 = 7;" in text
    assert 'pub const WIRE_TAG: &\'static str = "#t7:";' in text
    assert "callers must not reinterpret them" in text
    assert "as SENS Numbers" in text

    wire = WIRE_TEST.read_text(encoding="utf-8")
    assert 'Text7::from_canonical_wire_token("#q2:101010/1")' in wire
    assert "Err(Text7WireError::MissingTag)" in wire
    assert "existing_number_transport_law_is_unchanged" in wire


def main() -> None:
    source_contract_gate()

    same_bits = 0b0101010
    sound = D7Object(same_bits, "sound-cell")
    ordinal = D7Object(same_bits, "local-ordinal")
    number = ArithmeticNumber(same_bits)

    # Same seven physical bits, three distinct semantic objects.
    assert semantic_key(sound) != semantic_key(ordinal)
    assert semantic_key(ordinal) != semantic_key(number)
    assert semantic_key(sound) != semantic_key(number)

    # Roles cannot silently coerce inside D7.
    try:
        require_role(sound, "local-ordinal")
    except RoleError as exc:
        assert str(exc) == "ROLE-MISMATCH"
    else:
        raise AssertionError("sound silently became ordinal")

    try:
        require_role(ordinal, "sound-cell")
    except RoleError as exc:
        assert str(exc) == "ROLE-MISMATCH"
    else:
        raise AssertionError("ordinal silently became sound")

    # Arithmetic Number laws reject both D7 roles.
    mismatch_cases = 0
    for value in (sound, ordinal):
        for op, args in (
            (arithmetic_add, (value, ArithmeticNumber(1))),
            (arithmetic_mul, (value, ArithmeticNumber(2))),
            (arithmetic_recip, (value,)),
        ):
            try:
                op(*args)
            except DomainError as exc:
                assert str(exc) == "DOMAIN-MISMATCH"
                mismatch_cases += 1
            else:
                raise AssertionError((value, op.__name__))

    # Arithmetic works only in its own domain.
    assert arithmetic_add(number, ArithmeticNumber(1)) == ArithmeticNumber(same_bits + 1)
    assert arithmetic_mul(number, ArithmeticNumber(2)) == ArithmeticNumber(same_bits * 2)

    # Role erasure demonstrates ambiguity, not a default interpretation.
    assert erase_role(sound) == erase_role(ordinal) == same_bits
    try:
        interpret_erased_d7(same_bits)
    except RoleError as exc:
        assert str(exc) == "AMBIGUOUS-WITHOUT-ROLE"
    else:
        raise AssertionError("role-erased D7 bits were guessed")

    # Width gate is exact and fail-closed.
    for bits in (0, 1, 42, 127):
        assert D7Object(bits, "sound-cell").bits == bits
        assert D7Object(bits, "local-ordinal").bits == bits

    width_failures = 0
    for bits in (-1, 128, 255):
        try:
            D7Object(bits, "local-ordinal")
        except WidthError:
            width_failures += 1
        else:
            raise AssertionError(bits)

    # A local ordinal may point to a D14 rule node for provenance, but the
    # resulting object is a provenance link only; no D14 grammatical law is
    # imported into D7.
    provenance = D14ProvenanceLink(ordinal, "panini-node:opaque")
    assert semantic_key(provenance)[0] == "D7->D14-provenance"
    assert provenance.ordinal == ordinal

    # There is deliberately no occupancy claim: width-valid != admitted resident.
    width_valid_coordinate_count = 128

    print("OWNER-D7-RATIFICATION=PASS")
    print("D7-WIDTH=7")
    print("D7-ROLES=sound-cell,local-ordinal")
    print("SAME-BITS-SOUND-VS-ORDINAL=DISTINCT")
    print("SAME-VALUE-ORDINAL-VS-NUMBER=DISTINCT")
    print(f"ARITHMETIC-DOMAIN-MISMATCH-CASES={mismatch_cases}")
    print("ROLE-ERASURE=AMBIGUOUS-WITHOUT-ROLE")
    print(f"WIDTH-FAILURES={width_failures}")
    print("TEXT7-VS-NUMBER-WIRE=SEPARATE")
    print("D14-LINK=PROVENANCE-ONLY")
    print(f"WIDTH-VALID-COORDINATES={width_valid_coordinate_count}")
    print("OCCUPANCY-CLAIM=NONE")
    print("STATUS=PASS-RATIFIED-D7-CONFORMANCE")
    print("AUTHORITY=OWNER-RATIFIED-DOMAIN;RESEARCH-WITNESS")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""#2739 — generate D7 LocalOrdinal provenance corpus from pinned Shiva-sutra canon.

This is a role-tagged provenance projection, not arithmetic Number semantics.

The donor's 1..14 IDs/source order are projected into exact 7-bit D7 local
ordinals. No grammar relation is inferred from adjacency or numbering.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import re
import sys
from dataclasses import dataclass
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
LOCK = ROOT / "contracts" / "d7-local-ordinal.lock"
OUTPUT = ROOT / "benchmarks" / "d7-local-ordinal-corpus" / "fixtures" / "projection.json"


def quoted(text: str, name: str) -> str:
    m = re.search(r"\(" + re.escape(name) + r'\s+"([^"]+)"\)', text)
    if not m:
        raise SystemExit(f"missing {name} in {LOCK}")
    return m.group(1)


def integer(text: str, name: str) -> int:
    m = re.search(r"\(" + re.escape(name) + r"\s+(\d+)\)", text)
    if not m:
        raise SystemExit(f"missing {name} in {LOCK}")
    return int(m.group(1))


def git_blob_sha1(data: bytes) -> str:
    header = f"blob {len(data)}\0".encode("ascii")
    return hashlib.sha1(header + data).hexdigest()


def parse_canon(path: Path) -> list[dict[str, object]]:
    """Strictly parse only the simple transmitted-canon fields we project.

    This is intentionally not a general YAML parser. Unexpected structure fails
    rather than becoming a hidden semantic dependency.
    """
    rows: list[dict[str, object]] = []
    current: dict[str, object] | None = None

    id_re = re.compile(r"^\s*- id:\s*(\d+)\s*$")
    text_re = re.compile(r'^\s*text_iast:\s*"([^"]*)"\s*$')

    for raw in path.read_text(encoding="utf-8").splitlines():
        m = id_re.match(raw)
        if m:
            if current is not None:
                if "text_iast" not in current:
                    raise SystemExit(f"missing text_iast for donor id {current['id']}")
                rows.append(current)
            current = {"id": int(m.group(1))}
            continue

        m = text_re.match(raw)
        if m and current is not None:
            if "text_iast" in current:
                raise SystemExit(f"duplicate text_iast for donor id {current['id']}")
            current["text_iast"] = m.group(1)

    if current is not None:
        if "text_iast" not in current:
            raise SystemExit(f"missing text_iast for donor id {current['id']}")
        rows.append(current)

    if not rows:
        raise SystemExit("no donor sutras parsed")
    return rows


def validate_source_order(sutras: list[dict[str, object]]) -> None:
    ids = [int(row["id"]) for row in sutras]
    if ids != list(range(1, 15)):
        raise SystemExit(f"donor source-order drift: {ids!r}")


def bits7(value: int) -> str:
    if not 0 <= value < 128:
        raise ValueError("D7 width overflow")
    return format(value, "07b")


@dataclass(frozen=True)
class D7SoundCell:
    bits: int


@dataclass(frozen=True)
class D7LocalOrdinal:
    bits: int
    donor_ref: str


@dataclass(frozen=True)
class ArithmeticNumber:
    value: int


class DomainMismatch(TypeError):
    pass


def arithmetic_add(left, right):
    if not isinstance(left, ArithmeticNumber) or not isinstance(right, ArithmeticNumber):
        raise DomainMismatch
    return ArithmeticNumber(left.value + right.value)


def arithmetic_mul(left, right):
    if not isinstance(left, ArithmeticNumber) or not isinstance(right, ArithmeticNumber):
        raise DomainMismatch
    return ArithmeticNumber(left.value * right.value)


def arithmetic_recip(value):
    if not isinstance(value, ArithmeticNumber):
        raise DomainMismatch
    if value.value == 0:
        raise ZeroDivisionError
    return ("rational", 1, value.value)


def generate(upstream_root: Path) -> dict[str, object]:
    lock = LOCK.read_text(encoding="utf-8")
    rel = quoted(lock, "path")
    expected_blob = quoted(lock, "git-blob-sha1")
    revision = quoted(lock, "revision")
    width = integer(lock, "logical-width")
    count = integer(lock, "ordinal-count")

    if width != 7:
        raise SystemExit("D7 lock width drift")
    if count != 14:
        raise SystemExit("D7 ordinal count drift")

    donor = upstream_root / rel
    if not donor.is_file():
        raise SystemExit(f"missing pinned donor file: {donor}")

    actual_blob = git_blob_sha1(donor.read_bytes())
    if actual_blob != expected_blob:
        raise SystemExit(f"donor blob drift: {actual_blob} != {expected_blob}")

    sutras = parse_canon(donor)

    # Source-order is part of provenance. Reordering must invalidate the lock.
    validate_source_order(sutras)

    rows = []
    for source_order, donor in enumerate(sutras, start=1):
        ordinal = int(donor["id"])
        if ordinal != source_order:
            raise SystemExit("donor ordinal/source-order mismatch")
        rows.append(
            {
                "bits": bits7(ordinal),
                "ordinal_display": ordinal,
                "role": "local-shiva-sutra-ordinal",
                "donor_ref": f"shiva-sutra:{ordinal}",
                "source_order": source_order,
                "source_text_iast": donor["text_iast"],
                "law": "provenance/source-order-only",
                "d14_relation": "provenance-only",
                "arithmetic": "forbidden",
                "status": "D7-VALID-PROVENANCE",
            }
        )

    # Domain/role guards over real projected payloads.
    mismatch_cases = 0
    for row in rows:
        raw = int(row["bits"], 2)
        ordinal = D7LocalOrdinal(raw, row["donor_ref"])
        sound = D7SoundCell(raw)
        number = ArithmeticNumber(raw)

        assert ordinal != sound
        assert ordinal != number
        assert sound != number

        for operation, args in (
            (arithmetic_add, (ordinal, ArithmeticNumber(1))),
            (arithmetic_mul, (ordinal, ArithmeticNumber(2))),
            (arithmetic_recip, (ordinal,)),
        ):
            try:
                operation(*args)
            except DomainMismatch:
                mismatch_cases += 1
            else:
                raise AssertionError("D7 LocalOrdinal accepted arithmetic")

    # Role erasure is intentionally ambiguous: bits alone are insufficient.
    probe = int(rows[0]["bits"], 2)
    possible_roles = {
        type(D7SoundCell(probe)).__name__,
        type(D7LocalOrdinal(probe, rows[0]["donor_ref"])).__name__,
        type(ArithmeticNumber(probe)).__name__,
    }
    assert len(possible_roles) == 3

    return {
        "schema": "sens-d7-local-ordinal-corpus/v1",
        "authority": "owner-ratified-D7-provenance-projection",
        "upstream": {
            "repository": quoted(lock, "repository"),
            "revision": revision,
            "path": rel,
            "git_blob_sha1": expected_blob,
        },
        "logical_width": 7,
        "rows": rows,
        "counts": {
            "rows": len(rows),
            "arithmetic_domain_mismatch_cases": mismatch_cases,
            "occupied_local_ordinals": 14,
            "remaining_d7_occupancy_claim": 0,
        },
        "guards": {
            "same_bits_sound_vs_ordinal": "DISTINCT",
            "same_value_ordinal_vs_number": "DISTINCT",
            "arithmetic_on_local_ordinal": "DOMAIN-MISMATCH",
            "d14_link": "PROVENANCE-ONLY",
            "ordinal_adjacency_implies_grammar": False,
            "blanket_d7_occupancy": False,
        },
    }


def self_test(upstream_root: Path) -> None:
    lock = LOCK.read_text(encoding="utf-8")
    donor = upstream_root / quoted(lock, "path")
    sutras = parse_canon(donor)
    validate_source_order(sutras)

    # Sensitivity: a donor-order mutation must be rejected independently of
    # the outer blob lock. This proves source order is a checked provenance
    # invariant rather than merely a comment on the pinned blob.
    swapped = [dict(row) for row in sutras]
    swapped[0], swapped[1] = swapped[1], swapped[0]
    try:
        validate_source_order(swapped)
    except SystemExit:
        pass
    else:
        raise AssertionError("D7 donor reorder mutation was not rejected")

    # Role erasure must leave the raw payload ambiguous across admitted
    # interpretation classes; bits alone never choose Sound/Ordinal/Number.
    probe = 1
    interpretations = {
        (type(D7SoundCell(probe)).__name__, bits7(probe)),
        (type(D7LocalOrdinal(probe, "shiva-sutra:1")).__name__, bits7(probe)),
        (type(ArithmeticNumber(probe)).__name__, bits7(probe)),
    }
    assert len(interpretations) == 3

    print("D7-LOCAL-ORDINAL-REORDER-SENSITIVITY=PASS")
    print("D7-LOCAL-ORDINAL-ROLE-ERASURE-AMBIGUITY=PASS")


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--upstream-root", type=Path, required=True)
    ap.add_argument("--check", action="store_true")
    ap.add_argument("--self-test", action="store_true")
    args = ap.parse_args()

    upstream_root = args.upstream_root.resolve()
    if args.self_test:
        self_test(upstream_root)

    payload = generate(upstream_root)
    rendered = json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True) + "\n"

    if args.check:
        if not OUTPUT.is_file():
            print(f"missing generated projection: {OUTPUT}", file=sys.stderr)
            return 1
        if OUTPUT.read_text(encoding="utf-8") != rendered:
            print("D7 local ordinal projection is stale", file=sys.stderr)
            return 1
    else:
        OUTPUT.write_text(rendered, encoding="utf-8")

    print(f"D7-LOCAL-ORDINAL-ROWS={payload['counts']['rows']}")
    print("D7-WIDTH=7")
    print("ORDINAL-RANGE=1..14")
    print("SOURCE-ORDER=PINNED-PROVENANCE")
    print(
        "ARITHMETIC-DOMAIN-MISMATCH-CASES="
        + str(payload["counts"]["arithmetic_domain_mismatch_cases"])
    )
    print("SAME-BITS-SOUND-VS-ORDINAL=DISTINCT")
    print("SAME-VALUE-ORDINAL-VS-NUMBER=DISTINCT")
    print("D14-LINK=PROVENANCE-ONLY")
    print("D14-GRAMMAR-FROM-ADJACENCY=REJECTED")
    print("BLANKET-D7-OCCUPANCY=NONE")
    print("STATUS=PASS-D7-LOCAL-ORDINAL-CORPUS")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
